def d(n):
    """Calculate the sum of proper divisors of n."""
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i and n // i != n:
                divisors.append(n // i)
    return sum(divisors)

def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 to limit."""
    amicable_sum = 0
    for a in range(2, limit):
        b = d(a)
        if b > a and d(b) == a:
            amicable_sum += a + b
    return amicable_sum

