def max_aggregate(lst):
    # Create a dictionary to store the sum of aggregates for each name
    aggregate_dict = {}

    # Iterate through the list of tuples
    for name, value in lst:
        if name in aggregate_dict:
            aggregate_dict[name] += value
        else:
            aggregate_dict[name] = value

    # Find the name with the maximum aggregate
    max_name = max(aggregate_dict, key=aggregate_dict.get)
    max_value = aggregate_dict[max_name]

    return (max_name, max_value)

