# Alternative solution using two pointers (in-place for character array)
def replace_spaces_v8(s):
    # Convert string to list for in-place modification
    chars = list(s)
    # Count spaces
    space_count = chars.count(' ')
    # Calculate new length
    new_length = len(chars) + space_count * 2
    # Extend the list to new length
    chars.extend([None] * (new_length - len(chars)))

    # Use two pointers from end
    i = len(chars) - 1 - space_count * 2  # Original end
    j = len(chars) - 1  # New end

    while i >= 0:
        if chars[i] == ' ':
            chars[j] = '0'
            chars[j-1] = '2'
            chars[j-2] = '%'
            j -= 3
        else:
            chars[j] = chars[i]
            j -= 1
        i -= 1

    return ''.join(chars)

