# Alternative solution using a set to track visited nodes
def dict_depth_set(d, visited=None):
    if visited is None:
        visited = set()

    if id(d) in visited:
        return 0

    if not isinstance(d, dict) or not d:
        return 0

    visited.add(id(d))
    max_depth = 1

    for value in d.values():
        if isinstance(value, dict):
            depth = dict_depth_set(value, visited)
            max_depth = max(max_depth, 1 + depth)

    visited.remove(id(d))
    return

