def get_coordinates(coordinate):
    x, y = coordinate
    adjacent_coords = []
    for i in range(x-1, x+2):
        for j in range(y-1, y+2):
            if (i, j) != (x, y):  # Exclude the original coordinate
                adjacent_coords.append([i, j])
    return adjacent_coords

