def check_occurences(tuples_list):
    # Convert tuples to frozensets for case-insensitive comparison
    # and count occurrences using Counter
    counter = Counter(frozenset(t) for t in tuples_list)

    # Create result dictionary with original tuples as keys
    result = {}
    for t in tuples_list:
        frozen_t = frozenset(t)
        if counter[frozen_t] > 0:
            # Find the first occurrence of this frozenset
            original_tuple = None
            for item in tuples_list:
                if frozenset(item) == frozen_t:
                    original_tuple = item
                    break
            result[original_tuple] = counter[frozen_t]
            # Mark as processed to avoid duplicates
            counter[frozen_t] = 0

    return result

