def sphenic(n):
    def is_prime(num):
        if num<2:
            return False
        for i in range(2,int(num**0.5)+1):
            if num%i==0:
                return False
        return True

    count=0
    num=2
    while count<n:
        if is_prime(num) and is_prime(num+2) and is_prime(num+4):
            count+=1
            if count==n:
                return num*(num+2)*(num+4)
        num+=1
    return -1

