def validate(n):
    # Convert the number to a string to iterate over each digit
    s = str(n)

    # Count the frequency of each digit
    freq = {}
    for digit_char in s:
        digit = int(digit_char)
        if digit in freq:
            freq[digit] += 1
        else:
            freq[digit] = 1

    # Check if frequency of each digit is <= digit itself
    for digit, count in freq.items():
        if count > digit:
            return False

    return True

