# Alternative solution using stack
def dict_depth_stack(d):
    if not isinstance(d, dict) or not d:
        return 0

    stack = [d]
    depth = 0

    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            depth += 1
            stack.extend(current.values())

    return depth

print(dict_depth_stack({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using recursion with helper function
def dict_depth_helper(d, level=1):
    if not isinstance(d, dict) or not d:
        return level

    max_depth = level
    for value in d.values():
        if isinstance(value, dict):
            depth = dict_depth_helper(value, level + 1)
            max_depth = max(max_depth, depth)

    return max_depth

print(dict_depth_helper({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using iteration with queue
from collections import deque

def dict_depth_queue(d):
    if not isinstance(d, dict) or not d:
        return 0

    queue = deque([(d, 1)])
    max_depth = 0

    while queue:
        current_dict, depth = queue.popleft()
        max_depth = max(max_depth, depth)

        for value in current_dict.values():
            if isinstance(value, dict):
                queue.append((value, depth + 1))

    return max_depth

print(dict_depth_queue({'a':1, 'b': {'c': {'d': {}}}})) # 4

