import math
def sumofFactors6(n):
    total = 0
    for i in range(2, int(math.sqrt(n))+1):
        if n % i == 0:
            if i % 2 == 0:
                total += i
            if (n//i) % 2 == 0 and (n//i) != i:
                total += n//i
    return total

