def check_occurences(lst):
    # Convert each tuple to a canonical form where the smaller element comes first
    canonical_tuples = [tuple(sorted(t)) for t in lst]

    # Count occurrences using Counter
    counts = Counter(canonical_tuples)

    # Convert back to original tuple format if needed
    result = {}
    for key, count in counts.items():
        # Find the original tuple that matches this canonical form
        for original_tuple in lst:
            if tuple(sorted(original_tuple)) == key:
                result[original_tuple] = count
                break

    return result

