def replace_spaces_v8(s):
    # Convert string to bytearray for in-place modification
    arr = bytearray(s)
    # Count spaces
    space_count = arr.count(b' ')
    # Calculate new length
    new_length = len(arr) + space_count * 2
    # Resize array
    arr.extend([0] * (space_count * 2))
    # Replace spaces from end to beginning
    i = len(arr) - 1
    j = len(arr) - space_count * 2 - 1
    while j >= 0:
        if arr[j] == ord(' '):
            arr[i] = ord('0')
            arr[i-1] = ord('2')
            arr[i-2] = ord('%')
            i -= 3
        else:
            arr[i] = arr[j]
            i -= 1
        j -= 1
    return arr.decode()

