def bell_Number(n):
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        bell = [0] * (n + 1)
        bell[0] = 1
        for i in range(1, n + 1):
            bell[i] = 0
            for j in range(i):
                bell[i] += (bell[j] * comb(i - 1, j))
        return bell[n]

def comb(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c

