def sequence(n):
    if n <= 0:
        raise ValueError("n must be positive")
    if n == 1:
        return 1
    if n == 2:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 1
    dp[2] = 1
    for i in range(3, n + 1):
        dp[i] = dp[dp[i - 1]] + dp[i - dp[i - 1]]
    return dp[n]

