def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        divisors_sum = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                if i != n // i:  # Avoid counting the square root twice for perfect squares
                    divisors_sum += i + n // i
                elif i == n // i and i != n:  # Only count the square root once if it's not the number itself
                    divisors_sum += i
        return divisors_sum - n  # Exclude the number itself

    amicable_sum = 0
    for num in range(2, limit):
        sum_div = sum_of_divisors(num)
        if sum_div > num and sum_div < limit and sum_of_divisors(sum_div) == num:
            amicable_sum += num + sum_div

    return amicable_sum

