# Alternative solution using stack
def dict_depth_stack(d):
    if not isinstance(d, dict) or not d:
        return 0

    stack = [d]
    depth = 0

    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            depth += 1
            for value in current.values():
                stack.append(value)

    return depth

print(dict_depth_stack({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using recursion with max depth tracking
def dict_depth_recursive(d, current_depth=1):
    if not isinstance(d, dict) or not d:
        return current_depth - 1

    max_depth = current_depth
    for value in d.values():
        if isinstance(value, dict):
            depth = dict_depth_recursive(value, current_depth + 1)
            max_depth = max(max_depth, depth)

    return max_depth

print(dict_depth_recursive({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using collections.deque for BFS approach
from collections import deque

def dict_depth_bfs(d):
    if not isinstance(d, dict) or not d:
        return 0

    queue = deque([(d, 1)])
    max_depth = 1

    while queue:
        current_dict, depth = queue.popleft()
        max_depth = max(max_depth, depth)

        for value in current_dict.values():
            if isinstance(value, dict):
                queue.append((value, depth + 1))

    return max_depth

print(dict_depth_bfs({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using a helper function with global variable
def dict_depth_global_var(d):
    max_depth = [0]  # Using list to make it mutable

    def helper(current_dict, current_depth):
        if not isinstance(current_dict, dict) or not current_dict:
            max_depth[0] = max(max_depth[0], current_depth - 1)
            return

        for value in current_dict.values():
            if isinstance(value, dict):
                helper(value, current_depth + 1)
            else:
                max_depth[0] = max(max_depth[0], current_depth)

    helper(d, 1)
    return max_depth[0]

print(dict_depth_global_var({'a':1, 'b': {'c': {'d': {}}}})) # 4

