def divisible_by_digits(startnum, endnum):
    result = []
    for num in range(startnum, endnum + 1):
        str_num = str(num)
        # Check if the number contains zero
        if '0' in str_num:
            continue
        # Check if the number is divisible by each of its digits
        is_divisible = True
        for digit_char in str_num:
            digit = int(digit_char)
            if num % digit != 0:
                is_divisible = False
                break
        if is_divisible:
            result.append(num)
    return result

