from collections import Counter

def check_occurences(lst):
    # Convert tuples to canonical form (sorted elements)
    canonical_tuples = [tuple(sorted(t)) for t in lst]

    # Count occurrences
    counts = Counter(canonical_tuples)

    # Create result dictionary with original tuples
    result = {}
    for original_tuple in lst:
        canonical = tuple(sorted(original_tuple))
        if counts[canonical] > 0:
            result[original_tuple] = counts[canonical]
            counts[canonical] = 0  # Prevent duplicate entries

    return result

