# Let's also verify with a simple example
def get_total_number_of_sequences_simple(m, n):
    """
    Simple recursive approach with memoization for verification
    """
    memo = {}

    def helper(max_val, length):
        if length == 0:
            return 1
        if max_val <= 0 or length < 0:
            return 0

        if (max_val, length) in memo:
            return memo[(max_val, length)]

        result = 0
        # Try all possible values for the last element
        for val in range(1, max_val + 1):
            if length == 1:
                # Last element can be anything up to max_val
                result += 1
            else:
                # Previous element must be at most val/2
                result += helper(val // 2, length - 1)

        memo[(max_val, length)] = result
        return result

    return helper(m, n)

