def divisible_by_digits(startnum, endnum):
    result = []
    for num in range(startnum, endnum + 1):
        str_num = str(num)
        if '0' in str_num:
            continue
        divisible = True
        for digit_char in str_num:
            digit = int(digit_char)
            if num % digit != 0:
                divisible = False
                break
        if divisible:
            result.append(num)
    return result

