    if not isinstance(d, dict) or not d:
        return 0
    max_depth = 1
    for key, value in d.items():
        if isinstance(value, dict):
            current_depth = 1 + dict_depth2(value)
            max_depth = max(max_depth, current_depth)
    return max_depth

