# Alternative solution using stack
def dict_depth3(d):
    if not isinstance(d, dict) or not d:
        return 0

    stack = [d]
    max_depth = 0

    while stack:
        current_dict = stack.pop()
        max_depth += 1

        for value in current_dict.values():
            if isinstance(value, dict):
                stack.append(value)

    return max_depth

