        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5)+1, 2):
            if n % i == 0:
                return False
        return True

    # Check if a is less than 2 or greater than 99
    if a < 2 or a > 99:
        return False

    # Find all prime factors of a
    prime_factors = []
    temp_a = a
    for i in range(2, int(temp_a**0.5)+1):
        while temp_a % i == 0:
            if is_prime(i):
                prime_factors.append(i)
            temp_a //= i
    if temp_a > 1 and is_prime(temp_a):
        prime_factors.append(temp_a)

    # Check if there are exactly 3 prime factors and their product equals a
    if len(prime_factors) == 3:
        product = 1
        for factor in prime_factors:
            product *= factor
        return product == a
    return False

