def sequence(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        memo = [0] * (n + 1)
        memo[0] = 0
        memo[1] = 1
        memo[2] = 1
        for i in range(3, n + 1):
            memo[i] = memo[memo[i - 1]] + memo[i - memo[i - 1]]
        return memo[n]

print(sequence(10)) # 6

