def sequence_recursive(n, memo={}):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        if n in memo:
            return memo[n]
        else:
            memo[n] = sequence_recursive(memo[n-1], memo) + sequence_recursive(n-memo[n-1], memo)
            return memo[n]

print(sequence_recursive(10)) # 6

