    result = ""
    first_occurrence = -1
    last_occurrence = -1

    # Find first and last occurrences
    for i in range(len(str)):
        if str[i] == ch:
            if first_occurrence == -1:
                first_occurrence = i
            last_occurrence = i

    # Build result string excluding first and last occurrences
    for i in range(len(str)):
        if i != first_occurrence and i != last_occurrence:
            result += str[i]

    return result

