print(is_majority([1, 1, 2, 4, 4, 4, 6, 6], 8, 4))  # False
print(is_majority([1, 1, 1, 2, 2], 5, 1))  # True
print(is_majority([1, 2, 3, 4, 5], 5, 3))  # False

