# Alternative approach using collections.deque for BFS-like traversal
from collections import deque

def dict_depth_bfs(d):
    if not isinstance(d, dict) or not d:
        return 0

    queue = deque([(d, 1)])
    max_depth = 1

    while queue:
        current_dict, current_level = queue.popleft()
        max_depth = max(max_depth, current_level)

        for value in current_dict.values():
            if isinstance(value, dict):
                queue.append((value, current_level + 1))

    return max_depth

print(dict_depth_bfs({'a':1, 'b': {'c': {'d': {}}}})) # 4

