def dict_depth_iterative(d):
    if not isinstance(d, dict) or not d:
        return 0

    max_depth = 1
    current_level = 1
    items = list(d.items())

    while items:
        key, value = items.pop()
        if isinstance(value, dict):
            current_level += 1
            items.extend(value.items())
            max_depth = max(max_depth, current_level)
        else:
            current_level = 1

    return max_depth

